import csv
from common import *


def main():
    measured=json.loads((HERE/'omissions.json').read_text())
    analysis=json.loads((HERE/'analysis.json').read_text())
    validation=json.loads((HERE/'validation.json').read_text())
    rows=measured['rows'];strict=[r for r in rows if r['category']=='strict_rd_improvement']
    def save(name,lines):(HERE/name).write_text('\n'.join(lines)+'\n',encoding='utf-8',newline='\n')
    lines=['# Pass 24 final-patch redundancy','','Stop at the completed-stream omission feasibility gate. Three strict RD improvements exist, but their final-file savings are only 14, 74 and 97 bytes. No sampled omission reaches 5% savings with at most 1% RGB MSE growth. This does not justify a pruning algorithm, cheap working-SSE predictor or integrated encoder experiment. Only this feasibility report and the summary are created; no postencode-pruning report.','','Control: unchanged pbc31_feature_histogram at 1c9c4016fdb213d7d16663542d268c7c3df4ed9b; research start 5d1b3a1f0db036dfef0dd9d51c6898802f7d48d8. Four existing ordinary images, Quality/HQ, default 250k working cap, seed 2003/release RNG/model/configs preserved. Saved Pass17 streams are checked by exact stream/pixel SHA256 and original-size RGB MSE. Existing parser/serializer reproduces every original byte on all 8 files. No full image encode ran in this pass.','','Sampling: keep all 3 initialization patches. Select 10 iterative patches per file from deterministic first/second, quartile/median/three-quarter, last-two positions plus largest raw-cost and most-overlapped candidates, deduplicated/fill in ascending order. This yields 80 tests from 233 iterative patches. All sampled indices and every original patch geometry/channel/grid size/effective bit depth/raw serialized cost/later overlap are retained in omissions.json. Positions are zero-based original serialized indices; first iterative index is 3. These are middle-of-completed-stream omissions, not prefix truncations or fresh lower-budget encodes.','','Every test removes exactly one iterative patch, updates the header count through the existing serializer, uses production LZMA/framing and independently invokes the ordinary decoder. True original-resolution RGB MSE includes signed int16 canvas reconstruction, clipping, YCbCr conversion and final PIL bicubic resizing. No inference from historical local patch gain or raw-bit ownership. All survivors retain their original order/values.','','| Image | Preset | Sampled / iterative | RGB-MSE-reducing omissions | Strict RD improvements |','| --- | --- | ---: | ---: | ---: |']
    for r in analysis['summary']:lines.append(f"| {r['image']} | {r['preset']} | {r['samples']} / {r['available_iterative']} | {r['rgb_mse_improving']} | {r['strict_count']} |")
    improving=sum(r['mse_change']<0 for r in rows)
    lines+=['',f'RGB MSE decreases in {improving}/80 sampled omissions (8.75%); only 3/80 (3.75%) also reduce final bytes. No exact MSE ties. The other 4 MSE-reducing omissions grow the file. Categories: 3 strict, 28 low-loss rate-saving trades, 3 negligible effects, 46 outside the low-loss screen. Outside-screen is a screening label, not a theorem that every larger distortion trade is dominated.','','Exact strict improvements:','','| Image / preset | Omitted index | Original -> omitted bytes | Bytes saved | Original -> omitted RGB MSE | Rate change | MSE change |','| --- | ---: | ---: | ---: | ---: | ---: | ---: |']
    for r in strict:lines.append(f"| {r['image']} / {r['preset']} | {r['patch']} | {r['baseline_bytes']:,} -> {r['bytes']:,} | {-r['byte_change']} | {r['baseline_rgb_mse']:.6f} -> {r['rgb_mse']:.6f} | {r['rate_change_percent']:+.4f}% | {r['mse_change_percent']:+.4f}% |")
    lines+=['','These are valid strict pointwise wins across Googlewiki/Flower, but 0.048-0.161% final-file savings are too small for the requested practical direction. The frozen magnitude check requires at least 3 strict removals saving 0.5% each across 2 images, or 5% savings within 1% MSE growth across 2 images. Neither passes. Counts alone would conceal the tiny benefits.','','Best actual byte-saving omission within 1% MSE growth in each stream, with the original completed file as control:','','| Image / preset | Index | Final rate change | RGB MSE change |','| --- | ---: | ---: | ---: |']
    for r in analysis['summary']:lines.append(f"| {r['image']} / {r['preset']} | {r['best_low_loss_patch']} | {r['best_low_loss_rate_change_percent']:+.4f}% | {r['best_low_loss_mse_change_percent']:+.4f}% |")
    lines+=['','The largest low-loss saving is Googlewiki Quality 3.213% at 0.688% more MSE. Every image other than Googlewiki stays below 0.5% saving in this tolerance. A near-threshold Cat HQ omission (index 8) saves 10.492% but increases MSE 1.172%; it is explicitly retained, not silently dropped at the 1% boundary. No combination of these independent points is used to manufacture a joint gain.','','Patch position, overlap and precision:','','| Group | Sample count | MSE decreases | Strict RD | Low-loss byte savings | Median MSE change | Median final rate change |','| --- | ---: | ---: | ---: | ---: | ---: | ---: |']
    for label in ('early','middle','late','overlap_at_least_half','overlap_below_half','effective_bits_1to3','effective_bits_4plus','quality','high_quality'):
        r=analysis['groups'][label]
        lines.append(f"| {label} | {r['count']} | {r['mse_improving']} | {r['strict']} | {r['low_loss_saving']} | {r['median_mse_change_percent']:+.4f}% | {r['median_rate_change_percent']:+.4f}% |")
    lines+=['','Early/middle/late divide accepted iterative positions into thirds. Later-patch omission generally causes less damage and saves fewer bits; late patches are not more substantial redundant opportunities. All 3 strict omissions have effective depth 2 or 3. None of 58 sampled depth 4+ patches improves MSE when removed. Earlier costly/high-depth corrections remain important despite later additive overlap.','','Overlap is the fraction of the patch rectangle covered by the union of later same-component patch support. It is additive overlap, not literal overwrite. At overlap at least 50%, median omission MSE damage is 22.06%, versus 1.28% below 50%. This pooled association is confounded by patch size/position/content and does not show that overlap causes usefulness. Strict wins occur at overlaps 62.02%, 0% and 1.83%, so overlap alone does not identify them.','','Descriptive pooled Spearman correlations with signed MSE increase: position fraction -0.827, later overlap +0.467, effective depth +0.740, raw patch bits +0.831. No predictor was fitted or validated. These deliberately selected structural samples do not estimate the population frequency of redundant patches; group medians do not describe a deployable selection policy.','','Two-stage rate behavior matters. Googlewiki Quality index 6 removes 689 raw patch bits and reduces MSE 0.0130%, yet its recompressed file grows 43 bytes. Cat has three tiny MSE-reducing omissions that also grow the file. Raw patch cost is not marginal post-LZMA byte ownership. All 80 results use actual completed-file bytes/bpp, and all signed byte/MSE deltas are preserved.','','Ordinary RD controls: reuse the verified saved Q/HQ, HQ-p10, Quality-p10 and prior targeted controls, including Googlewiki HQ 500k, from the unchanged Pass23 control manifest. No new controls or larger-resolution candidates are encoded. Exact parent Q/HQ controls were independently revalidated in this pass. Selected strict/best-low-loss/near-threshold comparisons follow. Near-rate means within 5%, with signed gaps; no equal-rate claim.','','| Image / preset / index | Best actual control within 5% | Signed rate gap | MSE change vs actual control | Ordinary interpolated MSE change |','| --- | --- | ---: | ---: | ---: |']
    for r in analysis['chosen_control_comparisons']:
        near=r['best_measured_within5pct'];estimate=r['interpolated_mse_change_percent']
        lines.append(f"| {r['image']} / {r['preset']} / {r['patch']} | {near['preset'] if near else 'none'} | {format(near['signed_rate_gap_percent'],'+.4f')+'%' if near else '-'} | {format(near['mse_change_percent'],'+.4f')+'%' if near else '-'} | {format(estimate,'+.4f')+'%' if estimate is not None else '-'} |")
    lines+=['','Interpolation is the minimum MSE across valid measured bracketing chords, never extrapolated; endpoints/weights remain in analysis.json. It is a conservative sparse estimate, not an achievable equal-rate file. The broad Googlewiki quality-to500k bracket produces a much stronger estimate than default HQ and cannot be presented as actual dominance. The three strict omissions improve their actual same-preset points only slightly; this does not establish meaningful broad-frontier improvement. The Googlewiki Quality rate trade gives an estimated 0.84% matched-rate MSE gain, still small and isolated.','','The near-threshold Cat HQ index 8 file is 70,620 bytes/MSE 296.569203, compared with saved ordinary HQ-p10 at 70,524 bytes/MSE 298.416534: +0.1361% rate and -0.6190% MSE. The full measured ordinary bracket instead estimates a slight 0.0746% MSE regression. It is a small near-rate trade rather than evidence of a new large pruning opportunity.','','Offline evaluation cost, one warmed call per omission on i9-12900H logical P-core 12, numerical threads 1, Python 3.11.16/NumPy 2.4.6/Numba 0.68.0/Pillow 11.3.0. Actual serializer/decoder warmed on each original file first. Timers include serialization/LZMA, complete decoder and external true-source scoring; exclude file I/O, hashes and structural selection. Medians of distinct omissions are descriptive costs, not repeated performance estimates for one candidate. Component medians need not sum to the median full evaluation.','','| Image / preset | Median repack ms | Median decode ms | Median score ms | Median complete evaluation ms | Ten-test sum s |','| --- | ---: | ---: | ---: | ---: | ---: |']
    for r in analysis['summary']:lines.append(f"| {r['image']} / {r['preset']} | {r['repack_median_seconds']*1000:.2f} | {r['decode_median_seconds']*1000:.2f} | {r['score_median_seconds']*1000:.2f} | {r['evaluation_median_seconds']*1000:.2f} | {r['evaluation_total_seconds']:.3f} |")
    total=sum(r['evaluation_total_seconds'] for r in analysis['summary'])
    lines+=['',f'The 80 exact evaluations consume {total:.3f} s in these measured spans, before baseline roundtrip/warmup/selection/I/O. These are expensive offline diagnostics, not a shipping encoder mechanism. Complete encode-plus-pruning overhead and decode speedup are unmeasured because no integrated/pruned multi-removal candidate was justified. No rejected candidate receives repeated timing.','','Disposition: no C/D/E. Combined deletions, signed-canvas subtraction proxies, prediction cost, integrated encode overhead and additional-image generalization remain untested. It would be incorrect to add individual MSE/byte deltas to predict a joint result. There is insufficient useful signal to justify those conditional steps, or to spend more implementation effort classifying 14-97-byte wins. Existing geometric/bit-depth measurements do not establish a cheap practical predictor.','','Validation: 8 exact original parse/serialize/pixel/MSE checks; 80 actual omitted files independently decoded/scored; 80 saved-file header/count/initialization/survivor-order/hash checks; three strict files rescored; six fresh model-and-encoder-forbidden decoder processes (practical and immutable release v0 for each strict file). No new representation/decoder/model or online allocator, no full image encoding.','','The negative result is bounded: these completed streams contain very little exploitable sampled single-iterative-patch redundancy under preserved initialization. It does not prove global rate-allocation optimality, absence of unsampled/joint redundancy or a fundamental representation ceiling. Preserve the tiny strict wins and low-loss/near-threshold trades as measured evidence, and stop this postencode-removal direction.']
    save('PBC_FINAL_PATCH_REDUNDANCY.md',lines)
    lines=['# Pass 24 summary','','Stop after initial completed-stream feasibility. Eight saved ordinary Q/HQ files, 80 structurally selected iterative omissions out of 233 available patches. All initialization patches remain unchanged. Every test uses actual production LZMA repacking and independent ordinary v0 reconstruction against the original RGB source.','','1. Yes, sampled completed streams contain patches whose removal lowers RGB MSE: 7/80 (8.75%). Only 3/80 (3.75%) also shrink the final file. No exact MSE ties.','2. Strict savings are Googlewiki HQ index 10: 97 bytes (0.0548%), Flower Quality index 36: 14 bytes (0.0483%), Flower HQ index 13: 74 bytes (0.1605%). MSE reductions are 0.00128%, 0.00871%, 0.03577%. These are real but tiny pointwise wins, not a meaningful codec improvement.','3. No omission saves 5% within 1% MSE growth. Best low-loss trade is Googlewiki Quality: 3.213% fewer bytes/+0.688% MSE. Other images stay below 0.5% savings at that tolerance. Cat HQ index 8 saves 10.492% at +1.172% MSE, just outside the tolerance; compare it with ordinary HQ-p10 before interpreting that larger rate change.','4. Early/costly/high-depth patches generally remain important. Late omissions are usually low-impact but save very few bits. High later overlap does not imply redundancy: its sampled group has larger median omission MSE damage. All strict wins use 2-3 effective bits; none of 58 depth 4+ omissions improves MSE. These are descriptive biased-sample associations, not causal findings or a validated predictor.','5. Actual LZMA context can reverse raw savings: removing a 689-bit Googlewiki patch grows the file 43 bytes despite slightly improving MSE. Final bytes, not raw patch cost, determine every result.','6. Nearby ordinary controls leave only tiny leads. Cat HQ index 8 is +0.136% bytes/-0.619% MSE versus actual HQ-p10; its ordinary bracket estimate is slightly unfavorable. Googlewiki Quality has an estimated 0.84% matched-rate MSE gain, not 5-10%. Strict omissions dominate their actual default points by negligible amounts; broader-frontier claims are unsupported.','7. Combined removal behavior is untested. The predeclared meaningful-omission gate fails (no strict saving reaches 0.5%; no 5%-saving/1%-loss point), so no greedy multi-removal candidate, working-SSE proxy, integrated postprocessor, Monet/Eiffel extension or repeated rejected-candidate timing.','8. Cheap working-space predictability and prediction cost are therefore not established. Stored-cost/position/overlap statistics alone did not reveal meaningful removable rate. No oracle result is promoted as deployable.','9. Full encode-plus-pruning overhead is unmeasured; no image encoding ran. Exact oracle evaluation costs about 136-354 ms per omission median, 1.32-3.50 s for ten omissions per file, excluding structural selection/I/O. No decode speedup is established; measured individual decode spans are not matched repeated before/after benchmarks.','10. The hypothesis is not supported as a practical cross-content improvement on this bounded sample: graphics retains useful corrections, photographic strict wins are tiny and only Flower, and the larger Cat trade is not a clear frontier improvement. No integration or broad validation is warranted.','11. This establishes little exploitable sampled single-patch redundancy under fixed initialization, not globally optimal PBC allocation or absence of joint effects. Keep existing codec/allocation results intact; do not rescue this result with another pruning algorithm.','12. Eight exact original roundtrips and all 80 omitted streams pass byte/count/order/initialization validation; six fresh practical/release decoder processes reproduce the strict-file pixels with model loading and image encoding forbidden. Source/model/input/config/stream/pixel hashes and signed per-patch measurements are recorded.','','Reproduce from repository root with the existing Python 3.11 environment, ../research_pass17/requirements.txt, restored source images and saved ordinary Pass17 streams. Prior ordinary comparisons require the preserved Pass23 comparisons.json control manifest. Generated omitted streams remain ignored.','','```','research_pass16/.venv/Scripts/python.exe research_pass24/omissions.py','research_pass16/.venv/Scripts/python.exe research_pass24/analyze.py','research_pass16/.venv/Scripts/python.exe research_pass24/validate.py','research_pass16/.venv/Scripts/python.exe research_pass24/report.py','```','','The second requested pruning-results report is intentionally absent because no pruning stage beyond initial feasibility ran. Raw per-patch values/ledgers, exact selected indices, CPU/thread/warmup protocol and component timers accompany this summary. The 80-row CSV is compact evidence, not a large benchmark log.','','Practical pbc31_feature_histogram, model, v0, P21S/Pass22, frozen earlier results, HF and staging remain unchanged. ZIP SHA256: 08855cb3369000fd50d38fbb41d65920899998d366812c04519302383d873591. Focused source/tests/evidence are committed only to research/experiments; final verified GitHub commit and HEAD are supplied in the chat handoff. No protected branch, deployment, release/tag or staging change.']
    save('PBC_PASS24_SUMMARY.md',lines)
    fields=['image','preset','patch','channel','x','y','w','h','grid_size','effective_bit_depth','total_bits','later_same_component_overlap','iterative_fraction','baseline_bytes','bytes','byte_change','rate_change_percent','baseline_rgb_mse','rgb_mse','mse_change','mse_change_percent','bpp','category','repack_seconds','decode_seconds','score_seconds','evaluation_seconds','stream_sha256','pixels_sha256']
    with (HERE/'omissions.csv').open('w',newline='',encoding='utf-8') as file:
        writer=csv.DictWriter(file,fieldnames=fields,extrasaction='ignore',lineterminator='\n');writer.writeheader();writer.writerows(rows)
    result=meta();result.update(evidence_sha256={p.name:sha(p.read_bytes()) for p in HERE.iterdir() if p.suffix in ('.json','.csv') and p.name!='provenance.json'},saved_control_evidence_sha256=sha((ROOT/'research_pass17/baseline.json').read_bytes()),prior_control_manifest_sha256=analysis['prior_control_manifest_sha256'],phase_b_passed=False,combined_pruning_executed=False,cheap_proxy_executed=False,integrated_encoding_executed=False,full_image_encode_count=0,omission_file_count=len(rows),staged_zip_sha256_unchanged='08855cb3369000fd50d38fbb41d65920899998d366812c04519302383d873591')
    write('provenance.json',result)
    print('reports written; no meaningful multi-image omission opportunity, stopped at feasibility',flush=True)


if __name__=='__main__':main()
